mapper.select:
select enterprise_code, using_amount, total_amount, serial_number
from file_base.t_storage_space
where enterprise_code = #{enterpriseCode}

mapper.update:
update file_base.t_storage_space
set total_amount  = #{totalAmountBytes},
    serial_number = #{serialNumber}
where enterprise_code = #{enterpriseCode}
  and total_amount = #{rawTotalAmountBytes}

update file_base.t_storage_space
set using_amount = using_amount + #{usingBytes}
where enterprise_code = #{enterpriseCode}
  and using_amount + #{usingBytes} <= total_amount
  and using_amount + #{usingBytes} >= 0

update file_base.t_storage_space
set using_amount = using_amount - #{usingBytes}
where enterprise_code = #{enterpriseCode}
  and using_amount - #{usingBytes} >= 0
